#include "stdlib/math/base/special/boxcoxf.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/assert/is_positive_zerof.h"
#include "stdlib/math/base/special/lnf.h"
#include "stdlib/math/base/special/expm1.h"
#include "stdlib/constants/float32/ninf.h"

/**
* Computes a one-parameter Box-Cox transformation for a single-precision floating-point number.
*
* @param x         input value
* @param lambda    power parameter
* @return          Box-Cox transformation
*
* @example
* float v = stdlib_base_boxcoxf( 1.0f, 2.5f );
* // returns 0.0f
*/
float stdlib_base_boxcoxf( const float x, const float lambda ) {
	double lam;
	double y;

	if ( stdlib_base_is_nanf( x ) || stdlib_base_is_nanf( lambda ) ) {
		return 0.0f / 0.0f; // NaN
	}
	if ( stdlib_base_is_positive_zerof( x ) && lambda < 0.0f ) {
		return STDLIB_CONSTANT_FLOAT32_NINF;
	}
	if ( stdlib_base_absf( lambda ) < 1.0e-10f ) {
		return stdlib_base_lnf( x );
	}
	lam = (double)lambda;
	y = stdlib_base_expm1( lam * (double)stdlib_base_lnf( x ) ) / lam;
	return (float)y;
}
